export function sum(numbers) {
  return numbers.reduce((total, n) => total + n, 0);
}

check:
import test from "node:test";
import assert from "node:assert/strict";
import { sum } from "./solution.mjs";

test("empty array", () => assert.equal(sum([]), 0));
test("single number", () => assert.equal(sum([5]), 5));
test("negatives", () => assert.equal(sum([-1, -2, -3]), -6));
test("1..100", () => assert.equal(sum(Array.from({ length: 100 }, (_, i) => i + 1)), 5050));
